/* @lc app=leetcode id=1886 lang=kotlin */ class Solution { fun findRotation(mat: Array<IntArray>, target: Array<IntArray>): Boolean = (0..3).any { rot -> mat.indices.all { r -> mat.indices.all { c -> (rot == 0 && mat[r][c] == target[r][c]) || (rot == 1 && mat[mat.size - 1 - c][r] == target[r][c]) || (rot == 2 && mat[mat.size - 1 - r][mat.size - 1 - c] == target[r][c]) || (rot == 3 && mat[c][mat.size - 1 - r] == target[r][c]) } } } }